-- Curate geology, physics, SHS mathematics, and SHS science questions.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en, quiz_fil=v.quiz_fil, explanation_en=c.fact_en,
    explanation_fil=c.fact_fil, options=v.options::jsonb
FROM (VALUES
 ($$starter-geo-earthquake$$,$$A seismograph records sudden ground shaking after stress is released underground. What event does this indicate?$$,$$Nagtala ang seismograph ng biglang pagyanig matapos kumawala ang puwersa sa ilalim ng lupa. Anong pangyayari ito?$$,$$[{"en":"An earthquake","fil":"Lindol","correct":true},{"en":"A tide","fil":"Pagtaas-baba ng tubig-dagat","correct":false},{"en":"A rainstorm","fil":"Bagyo ng ulan","correct":false},{"en":"A landslide caused only by wind","fil":"Pagguho dahil lamang sa hangin","correct":false}]$$),
 ($$starter-geo-fault$$,$$Two blocks of rock move past each other along a fracture in Earth’s crust. What is the fracture called?$$,$$Gumalaw ang dalawang bloke ng bato sa magkabilang panig ng bitak sa crust ng Daigdig. Ano ang tawag sa bitak?$$,$$[{"en":"A fault","fil":"Fault o bitak","correct":true},{"en":"A mineral vein","fil":"Ugát ng mineral","correct":false},{"en":"A river delta","fil":"Delta ng ilog","correct":false},{"en":"A sediment layer","fil":"Patong ng latak","correct":false}]$$),
 ($$starter-geo-volcano-magma$$,$$Molten rock is still below Earth’s surface. What is it called before it erupts?$$,$$Nasa ilalim pa ng ibabaw ng Daigdig ang tunaw na bato. Ano ang tawag dito bago pumutok?$$,$$[{"en":"Magma","fil":"Magma","correct":true},{"en":"Lava","fil":"Lava","correct":false},{"en":"Ash","fil":"Abo","correct":false},{"en":"Sediment","fil":"Latak","correct":false}]$$),
 ($$starter-geo-igneous$$,$$Magma cools and hardens into rock. What rock type forms?$$,$$Lumamig at tumigas ang magma at naging bato. Anong uri ng bato ang nabuo?$$,$$[{"en":"Igneous rock","fil":"Batong igneous","correct":true},{"en":"Sedimentary rock","fil":"Batong sedimentary","correct":false},{"en":"Metamorphic rock","fil":"Batong metamorphic","correct":false},{"en":"Soil","fil":"Lupa","correct":false}]$$),
 ($$starter-geo-sedimentary$$,$$Layers of sand and shell fragments are pressed together over time. What rock type may form?$$,$$Napipiit sa paglipas ng panahon ang mga patong ng buhangin at piraso ng kabibe. Anong uri ng bato ang maaaring mabuo?$$,$$[{"en":"Sedimentary rock","fil":"Batong sedimentary","correct":true},{"en":"Igneous rock","fil":"Batong igneous","correct":false},{"en":"Metal alloy","fil":"Haluang metal","correct":false},{"en":"Magma","fil":"Magma","correct":false}]$$),
 ($$starter-geo-minerals$$,$$A geologist tests a naturally occurring solid with a definite composition and crystal structure. What is it?$$,$$Sinusuri ng geologist ang likas na solidong may tiyak na komposisyon at estrukturang kristal. Ano ito?$$,$$[{"en":"A mineral","fil":"Mineral","correct":true},{"en":"A fossil fuel","fil":"Fossil fuel","correct":false},{"en":"A manufactured plastic","fil":"Gawang-taong plastik","correct":false},{"en":"A sedimentary layer","fil":"Patong ng sediment","correct":false}]$$),
 ($$starter-geo-erosion$$,$$A river carries loosened soil downstream. Which process moves the sediment from its original location?$$,$$Tinatangay ng ilog pababa ang lumuwag na lupa. Anong proseso ang naglilipat sa sediment mula sa pinagmulan nito?$$,$$[{"en":"Erosion","fil":"Erosion o pagguho","correct":true},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Deposition","fil":"Deposisi","correct":false},{"en":"Crystallization","fil":"Pagkikristal","correct":false}]$$),
 ($$starter-physics-energy$$,$$A battery powers a lamp, which gives off light and heat. What happens to the battery’s stored energy?$$,$$Pinaiilaw ng baterya ang lampara na naglalabas ng liwanag at init. Ano ang nangyayari sa nakaimbak na enerhiya ng baterya?$$,$$[{"en":"It transforms into electrical energy, then light and heat.","fil":"Nagiging elektrikal na enerhiya ito, pagkatapos ay liwanag at init.","correct":true},{"en":"It disappears completely.","fil":"Lubusan itong nawawala.","correct":false},{"en":"It becomes matter with no transfer.","fil":"Nagiging bagay ito nang walang paglipat.","correct":false},{"en":"It changes only into sound.","fil":"Nagiging tunog lamang ito.","correct":false}]$$),
 ($$starter-physics-gravity$$,$$An astronaut releases a tool near a planet and it accelerates toward the planet. Which interaction causes the motion?$$,$$Binitiwan ng astronaut ang kagamitan malapit sa planeta at bumilis ito papunta rito. Anong interaksiyon ang sanhi ng galaw?$$,$$[{"en":"Gravitational attraction","fil":"Hatak ng grabidad","correct":true},{"en":"Buoyant force from water","fil":"Puwersang buoyancy mula sa tubig","correct":false},{"en":"Air resistance in a vacuum","fil":"Pagtutol ng hangin sa vacuum","correct":false},{"en":"Sound pressure","fil":"Presyon ng tunog","correct":false}]$$),
 ($$starter-physics-light-travel$$,$$A flashlight is switched on in a dark room. How does its light reach a wall across the room?$$,$$Binuksan ang flashlight sa madilim na silid. Paano nakararating sa pader ang liwanag nito?$$,$$[{"en":"Light travels from the source through space and air to the wall.","fil":"Naglalakbay ang liwanag mula sa pinagmulan sa hangin hanggang sa pader.","correct":true},{"en":"The wall sends light to the flashlight.","fil":"Nagpapadala ng liwanag ang pader sa flashlight.","correct":false},{"en":"Sound carries the light across.","fil":"Tunog ang nagdadala ng liwanag.","correct":false},{"en":"Air turns into light at the wall.","fil":"Nagiging liwanag ang hangin sa pader.","correct":false}]$$),
 ($$starter-physics-reflection$$,$$A mirror redirects a beam of light. What process causes the light to bounce from its surface?$$,$$Inilihis ng salamin ang sinag ng liwanag. Anong proseso ang nagpapatalbog sa liwanag mula sa ibabaw nito?$$,$$[{"en":"Reflection","fil":"Reflection o pagsasalamin","correct":true},{"en":"Refraction","fil":"Refraction","correct":false},{"en":"Absorption only","fil":"Pagsipsip lamang","correct":false},{"en":"Evaporation","fil":"Evaporation","correct":false}]$$),
 ($$starter-physics-refraction$$,$$A straw looks bent where it enters a glass of water because light changes direction between materials. What is this called?$$,$$Mukhang baluktot ang straw sa bahaging pumapasok ito sa baso ng tubig dahil nagbabago ang direksiyon ng liwanag sa magkaibang materyal. Ano ito?$$,$$[{"en":"Refraction","fil":"Refraction","correct":true},{"en":"Reflection","fil":"Reflection","correct":false},{"en":"Vibration","fil":"Panginginig","correct":false},{"en":"Condensation","fil":"Condensation","correct":false}]$$),
 ($$starter-physics-sound-vibration$$,$$A speaker cone moves back and forth as music plays. What physical motion produces the sound waves?$$,$$Pabalik-balik ang galaw ng cone ng speaker habang tumutugtog ang musika. Anong pisikal na galaw ang lumilikha ng sound wave?$$,$$[{"en":"Vibration","fil":"Panginginig","correct":true},{"en":"Reflection","fil":"Reflection","correct":false},{"en":"Freezing","fil":"Pagyeyelo","correct":false},{"en":"Magnetic poles separating","fil":"Paghihiwalay ng magnetic poles","correct":false}]$$),
 ($$starter-physics-sound-vacuum$$,$$A spacecraft is outside Earth’s atmosphere. Why can an astronaut not hear an unamplified explosion across empty space?$$,$$Nasa labas ng atmospera ng Daigdig ang spacecraft. Bakit hindi maririnig ng astronaut ang pagsabog sa bakanteng kalawakan?$$,$$[{"en":"Sound needs a material medium; a vacuum has no particles to carry it.","fil":"Nangangailangan ng materyal na medium ang tunog; walang partikulong magdadala nito sa vacuum.","correct":true},{"en":"Sound travels only in water.","fil":"Sa tubig lamang naglalakbay ang tunog.","correct":false},{"en":"Light blocks sound in space.","fil":"Hinaharangan ng liwanag ang tunog sa kalawakan.","correct":false},{"en":"The explosion has no energy.","fil":"Walang enerhiya ang pagsabog.","correct":false}]$$),
 ($$starter-shs-math-function$$,$$For every allowed x-value, a rule gives exactly one y-value. What kind of relation is this?$$,$$Para sa bawat pinapayagang halaga ng x, iisang halaga ng y ang ibinibigay ng tuntunin. Anong uri ng ugnayan ito?$$,$$[{"en":"A function","fil":"Function","correct":true},{"en":"A relation assigning two outputs to one input","fil":"Ugnayang nagbibigay ng dalawang output sa isang input","correct":false},{"en":"A set with no inputs","fil":"Set na walang input","correct":false},{"en":"A constant with no rule","fil":"Constant na walang tuntunin","correct":false}]$$),
 ($$starter-shs-math-domain$$,$$A function accepts x-values −2, 0, and 5. What is the set of these permitted inputs called?$$,$$Tumatanggap ang function ng x-values na −2, 0, at 5. Ano ang tawag sa set ng mga pinapayagang input?$$,$$[{"en":"The domain","fil":"Domain","correct":true},{"en":"The range","fil":"Range","correct":false},{"en":"The coefficient","fil":"Coefficient","correct":false},{"en":"The intercept only","fil":"Intercept lamang","correct":false}]$$),
 ($$starter-shs-math-rational-function$$,$$A formula has a polynomial in the numerator and x − 3 in the denominator. Which restriction must be applied?$$,$$May polynomial sa numerator at x − 3 sa denominator ang formula. Anong limitasyon ang dapat sundin?$$,$$[{"en":"Exclude x = 3 because it makes the denominator zero.","fil":"Alisin ang x = 3 dahil ginagawa nitong zero ang denominator.","correct":true},{"en":"Exclude every negative x-value.","fil":"Alisin ang lahat ng negative na x.","correct":false},{"en":"Allow x = 3 because zero is valid in a denominator.","fil":"Payagan ang x = 3 dahil puwede ang zero sa denominator.","correct":false},{"en":"Set the numerator equal to zero for all inputs.","fil":"Gawing zero ang numerator para sa lahat ng input.","correct":false}]$$),
 ($$starter-shs-math-simple-interest$$,$$A borrower pays interest only on the original amount borrowed each year. Which method is used?$$,$$Nagbabayad ng interes ang nangutang batay lamang sa orihinal na halagang hiniram bawat taon. Anong paraan ito?$$,$$[{"en":"Simple interest","fil":"Simple interest","correct":true},{"en":"Compound interest","fil":"Compound interest","correct":false},{"en":"An annuity","fil":"Annuity","correct":false},{"en":"Depreciation","fil":"Depreciation","correct":false}]$$),
 ($$starter-shs-math-compound-interest$$,$$A savings account adds interest to the balance, then calculates later interest on the new balance. What is this?$$,$$Idinadagdag ng savings account ang interes sa balanse at kinukuwenta ang susunod na interes batay sa bagong balanse. Ano ito?$$,$$[{"en":"Compound interest","fil":"Compound interest","correct":true},{"en":"Simple interest on principal only","fil":"Simple interest sa principal lamang","correct":false},{"en":"A one-time fee","fil":"Isahang bayad","correct":false},{"en":"A fixed annuity payment","fil":"Takdang bayad sa annuity","correct":false}]$$),
 ($$starter-shs-math-annuity$$,$$A worker deposits the same amount into a retirement account every month. What financial structure do these regular payments illustrate?$$,$$Parehong halaga ang inihuhulog ng manggagawa sa retirement account bawat buwan. Anong estrukturang pinansyal ang ipinakikita ng mga regular na bayad?$$,$$[{"en":"An annuity","fil":"Annuity","correct":true},{"en":"A single lump sum only","fil":"Isang malaking bayad lamang","correct":false},{"en":"A variable with no payments","fil":"Variable na walang bayad","correct":false},{"en":"A prime-number sequence","fil":"Sunod-sunod na prime number","correct":false}]$$),
 ($$starter-shs-math-proposition$$,$$“7 is an even number” can be judged true or false. What kind of mathematical statement is it?$$,$$Maaaring hatulan kung totoo o mali ang “7 ay even number.” Anong uri ng pahayag ito sa matematika?$$,$$[{"en":"A proposition","fil":"Proposition","correct":true},{"en":"A question with no truth value","fil":"Tanong na walang truth value","correct":false},{"en":"An expression with an unknown only","fil":"Expression na may unknown lamang","correct":false},{"en":"A command","fil":"Utos","correct":false}]$$),
 ($$starter-shs-math-syllogism$$,$$Premise 1: All mammals breathe air. Premise 2: A whale is a mammal. What conclusion follows?$$,$$Premise 1: Humihinga ng hangin ang lahat ng mammal. Premise 2: Mammal ang balyena. Anong konklusyon ang sumusunod?$$,$$[{"en":"A whale breathes air.","fil":"Humihinga ng hangin ang balyena.","correct":true},{"en":"A whale is a fish because it lives in water.","fil":"Isda ang balyena dahil nakatira ito sa tubig.","correct":false},{"en":"No mammals live in water.","fil":"Walang mammal na nakatira sa tubig.","correct":false},{"en":"All animals are whales.","fil":"Balyena ang lahat ng hayop.","correct":false}]$$),
 ($$starter-shs-science-variable$$,$$A student changes the amount of sunlight and measures plant growth. Which variable is the measured outcome?$$,$$Binabago ng mag-aaral ang dami ng sikat ng araw at sinusukat ang paglaki ng halaman. Aling variable ang sinusukat na resulta?$$,$$[{"en":"Plant growth is the dependent variable.","fil":"Dependent variable ang paglaki ng halaman.","correct":true},{"en":"Sunlight amount is the measured outcome.","fil":"Ang dami ng sikat ng araw ang sinusukat na resulta.","correct":false},{"en":"The pot color is always the outcome.","fil":"Laging resulta ang kulay ng paso.","correct":false},{"en":"The hypothesis is a variable.","fil":"Variable ang hypothesis.","correct":false}]$$),
 ($$starter-shs-science-control$$,$$A class tests whether fertilizer affects plant height. Which setup makes the comparison fair?$$,$$Sinusuri ng klase kung nakaaapekto ang pataba sa taas ng halaman. Aling setup ang patas na paghahambing?$$,$$[{"en":"Keep water, light, soil, and plant type the same; vary only fertilizer.","fil":"Panatilihing pareho ang tubig, liwanag, lupa, at uri ng halaman; pataba lamang ang baguhin.","correct":true},{"en":"Change fertilizer, water, and light together.","fil":"Sabay baguhin ang pataba, tubig, at liwanag.","correct":false},{"en":"Use different plant species in each group.","fil":"Gumamit ng magkaibang species sa bawat pangkat.","correct":false},{"en":"Measure one group at a different time.","fil":"Sukatin ang isang pangkat sa ibang oras.","correct":false}]$$),
 ($$starter-shs-science-atom$$,$$A model shows a tiny nucleus surrounded by electrons. What basic unit of ordinary matter is represented?$$,$$Ipinakikita ng modelo ang maliit na nucleus na napalilibutan ng electron. Anong pangunahing yunit ng karaniwang matter ito?$$,$$[{"en":"An atom","fil":"Atom","correct":true},{"en":"A tissue","fil":"Tissue","correct":false},{"en":"A planet","fil":"Planeta","correct":false},{"en":"A cell organ","fil":"Organelle","correct":false}]$$),
 ($$starter-shs-science-cell$$,$$A microscope slide shows a membrane-bound unit carrying out life processes. What level of organization is observed?$$,$$Ipinakikita ng microscope ang yunit na may lamad at nagsasagawa ng mga proseso ng buhay. Anong antas ng organisasyon ito?$$,$$[{"en":"A cell","fil":"Selula","correct":true},{"en":"An organ system","fil":"Organ system","correct":false},{"en":"A molecule only","fil":"Molekula lamang","correct":false},{"en":"An ecosystem","fil":"Ecosystem","correct":false}]$$),
 ($$starter-shs-science-photosynthesis$$,$$A plant uses light, water, and carbon dioxide to make sugar. What happens to some of the captured light energy?$$,$$Gumagamit ang halaman ng liwanag, tubig, at carbon dioxide upang gumawa ng asukal. Ano ang nangyayari sa bahagi ng enerhiyang liwanag na nakuha?$$,$$[{"en":"It is stored as chemical energy in energy-rich compounds.","fil":"Naiimbak ito bilang kemikal na enerhiya sa mga compound na mayaman sa enerhiya.","correct":true},{"en":"It is destroyed and cannot be transferred.","fil":"Nawawasak ito at hindi maililipat.","correct":false},{"en":"It becomes the plant’s mass without chemical change.","fil":"Nagiging masa ito ng halaman nang walang pagbabagong kemikal.","correct":false},{"en":"It turns directly into sound.","fil":"Direkta itong nagiging tunog.","correct":false}]$$),
 ($$starter-shs-science-mass$$,$$A reaction occurs in a sealed container. What should happen to the total mass before and after the reaction?$$,$$Nagaganap ang reaksiyon sa saradong lalagyan. Ano ang dapat mangyari sa kabuuang masa bago at pagkatapos nito?$$,$$[{"en":"It remains the same in the closed system.","fil":"Mananatili itong pareho sa saradong sistema.","correct":true},{"en":"It always doubles.","fil":"Laging dodoble.","correct":false},{"en":"It becomes zero.","fil":"Magiging zero.","correct":false},{"en":"It decreases because atoms vanish.","fil":"Bababa dahil nawawala ang mga atom.","correct":false}]$$),
 ($$starter-shs-science-earth-systems$$,$$Rainwater moves from the atmosphere onto land, then flows into the ocean. What does this illustrate about Earth’s systems?$$,$$Bumabagsak ang tubig-ulan mula sa atmospera patungo sa lupa at umaagos sa karagatan. Ano ang ipinakikita nito tungkol sa mga sistema ng Daigdig?$$,$$[{"en":"Earth systems exchange matter and energy across their boundaries.","fil":"Nagpapalitan ng matter at enerhiya ang mga sistema ng Daigdig sa magkakaugnay na hangganan.","correct":true},{"en":"Earth’s systems never interact.","fil":"Hindi nag-uugnayan ang mga sistema ng Daigdig.","correct":false},{"en":"Only the atmosphere contains matter.","fil":"Atmospera lamang ang may matter.","correct":false},{"en":"Water cannot move between systems.","fil":"Hindi makalilipat ng sistema ang tubig.","correct":false}]$$),
 ($$starter-shs-science-weather-climate$$,$$A report describes today’s temperature and rain; another summarizes typical conditions over decades. Which one describes climate?$$,$$Inilalarawan ng isang ulat ang temperatura at ulan ngayong araw; binubuod naman ng isa ang karaniwang kalagayan sa loob ng dekada. Alin ang tungkol sa klima?$$,$$[{"en":"The summary of long-term patterns","fil":"Buod ng pangmatagalang padron","correct":true},{"en":"Today’s temperature and rain","fil":"Temperatura at ulan ngayong araw","correct":false},{"en":"A single afternoon thunderstorm","fil":"Isang thunderstorm ngayong hapon","correct":false},{"en":"A one-day wind forecast","fil":"Pagtataya ng hangin sa isang araw","correct":false}]$$),
 ($$starter-shs-science-energy$$,$$A moving bicycle slows as its brakes warm. Which statement best describes the energy?$$,$$Bumabagal ang umaandar na bisikleta habang umiinit ang preno. Aling pahayag ang pinakamahusay na naglalarawan sa enerhiya?$$,$$[{"en":"Some motion energy is transferred and transformed into thermal energy.","fil":"Naililipat at nagiging thermal energy ang bahagi ng enerhiya ng galaw.","correct":true},{"en":"Energy disappears completely.","fil":"Lubusang nawawala ang enerhiya.","correct":false},{"en":"Heat turns into mass without transfer.","fil":"Nagiging masa ang init nang walang paglipat.","correct":false},{"en":"The bicycle creates energy from nothing.","fil":"Lumilikha ng enerhiya mula sa wala ang bisikleta.","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,options)
WHERE c.content_key=v.content_key;
